import json,pathlib,hashlib,datetime
from zoneinfo import ZoneInfo
R=pathlib.Path(__file__).resolve().parents[3];D=pathlib.Path(__file__).resolve().parent
acq=json.loads((R/'docs/acquisition/new-gpt-20261108-64.json').read_text());rows=acq['downloadedImages'];qs=json.loads((R/'site/dist/data.json').read_text())['questions'];bank=[c for q in qs for c in q.get('groupQuestions') or [q]]
def save(p,v):p.write_text(json.dumps(v,ensure_ascii=False,indent=2)+'\n')
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
manifest={'sourceId':'src-more-064','items':[]}
def add(seq,rownum,num,subject,title,stem,opts,correct,analyses,explanation,passage='',tables=None,figures=None,student='',tags=None,sources=None):
 ident=f'q-{981+seq*3}';row=rows[rownum-1];date=datetime.datetime.fromtimestamp(row['firstQuestionTimestamp'],ZoneInfo('Asia/Taipei')).date().isoformat();crop=D/f'evidence/q-{num}-original.png';question=stem+'\n'+'\n'.join(f'({l}) {t}' for l,t in zip('ABCD',opts))
 label={'Geography':'地理','History':'歷史','Civics':'公民'}[subject]
 q=dict(id=ident,sourceId='src-more-064',subject=subject,title=f'{label}第{num}題｜'+title,chapter='綜合',volume='綜合',date=date,dateLabel='首次出題日期',addedAt='2026-11-08',question=question,answer=f'({correct}) {opts["ABCD".index(correct)]}',explanation=explanation,trap='',verification='原卷逐題核對',verificationNote='已實開真正上傳原卷及本題裁圖，核對完整題幹、四選項及必要材料；原題日期取使用者首次提問的台灣日期，並非實際考試日。冊次、章節無證據歸綜合。',diagram='',notes='',status='todo',starred=False,tags=tags or [],images=[str(crop.relative_to(R))],sourceLabel=f'分享原卷｜第{num}題',studentAnswer=student,contentStatus='完整原題',correctOption=correct,passage=passage,optionAnalysis=[dict(label=l,text=t,wordClass='應選' if l==correct else '不選',meaning='',explanation=e) for l,t,e in zip('ABCD',opts,analyses)],tables=tables or [],questionFigures=figures or [],explanationFigures=[],originalQuestionNumber=str(num),sourceEvidence=dict(url=acq['url'],messageId=row['messageId'],messageIndex=row['messageIndex'],firstQuestionTimestamp=row['firstQuestionTimestamp'],firstQuestionDateTime=datetime.datetime.fromtimestamp(row['firstQuestionTimestamp'],ZoneInfo('Asia/Taipei')).isoformat(),originals=[{k:row[k] for k in ['fileId','path','sha256','bytes']}],inclusionEvidence=f'使用者明示{num}@錯題，本題原卷有紅筆訂正，已實開核對。',cropSHA256=sha(crop)))
 candidates=[dict(id=x['id'],title=x['title']) for x in bank if any(t in x.get('question','')+x.get('passage','') for t in tags or [])]
 duplicate=dict(exactMatch=False,method='正式題庫與groupQuestions完整題幹/全部選項/必要圖條件比對，主題近似不合併；source63重疊前19張已由另一製作線承接，這裡僅第20張起新增提問。',candidateCount=len(candidates),candidates=candidates[:20])
 rv=dict(id=ident,reviewerAgent='/root/comic_lane_2',originalVisualChecked=True,completeOriginalAndOptions=True,sourceGeneratedArtUsed=False,actualViewed=[row['path'],str(crop.relative_to(R))]+[f['src'] for f in figures or []],duplicateReview=duplicate,inclusionEvidence=q['sourceEvidence']['inclusionEvidence'],sourceUrl=acq['url'],originalQuestionNumber=str(num),checkedAt=datetime.datetime.now(datetime.timezone.utc).isoformat(),correction=None,supportingSources=sources or [])
 p=D/f'{ident}.json';r=D/f'{ident}-review.json';save(p,q);save(r,rv);manifest['items'].append(dict(id=ident,status='ready',questionPath=str(p.relative_to(R)),questionSHA256=sha(p),reviewPath=str(r.relative_to(R)),reviewSHA256=sha(r)));save(D/'manifest.json',manifest);return q,rv
add(0,20,3,'Geography','東北重工業的產業升級','黑龍江省、吉林省和遼寧省因礦產資源豐富，是中國最早發展重工業的地區，發展過程中因為當地的經濟過度倚賴重工業發展，受到產業結構失衡、環境汙染與礦產逐漸枯竭等問題影響而逐漸沒落。中國政府為改善當地經濟發展，最適合推動下列何項計畫？',['更新工廠的老舊設備，推動產業升級','串聯珠江，發展成中國北部交通樞紐','利用夏季西南季風發展風力發電，解決缺電問題','與鄰近的東南亞國家合作，在邊境增設經濟特區'],'A',['更新設備可提高效率、減少耗能和污染，配合產業轉型，直接回應老工業區的衰退原因。','珠江位於中國南方，不在東北三省，無法據此發展北部交通樞紐。','題目重點是產業結構、污染及資源枯竭，不是缺電；發展風電也不能只憑夏季西南季風判斷。','中國東北三省不與東南亞國家接壤，地理位置不符。'],'選A。題目先給東北三省的優勢：煤、鐵等資源豐富，較早發展重工業；再指出過度倚賴單一產業、設備與污染及資源枯竭帶來的衰退。更新工廠設備並推動產業升級，最能直接改善這些問題。\n\n其他選項先檢查地理位置：珠江在南方；東北三省也不在東南亞邊境。C把題目未提及的缺電當成主因，不能由季風名稱直接推論是最佳政策。',student='原卷藍筆C，紅筆訂正A。',tags=['東北三省','產業升級','重工業'])
add(1,21,16,'Geography','離島觀光行程與地圖位置','隨著新冠肺炎疫情趨緩，各地興起「報復性旅遊」風潮，快樂旅行社趁勢推出臺灣離島的套裝行程，如表（一）所示。若遊客想依照表中的規畫，按照順序從行程一遊玩到行程三，應該依序前往圖（六）中哪些離島旅遊？',['甲→丙→丁','甲→戊→己','乙→丙→己','乙→丁→戊'],'C',['行程一應是金門（乙），不是馬祖（甲）；行程三應是蘭嶼（己），不是小琉球（丁）。','前兩個位置不符：古寧頭在金門乙，柱狀玄武岩行程指向澎湖丙，不是綠島戊。','行程一古寧頭與高粱酒為金門乙；行程二玄武岩及水上活動為澎湖丙；行程三達悟族拼板舟、大天池為蘭嶼己。','行程二不是小琉球丁，行程三達悟族與大天池也不是綠島戊。'],'選C，乙→丙→己。先用各行程的代表景點辨認離島，再回到原圖找代號。\n\n行程一提到古寧頭戰史館、戰地史蹟及高粱酒，是金門，原圖乙。行程二以柱狀玄武岩及水上活動為重點，是澎湖，原圖丙。行程三明示達悟族拼板舟及大天池，是蘭嶼，原圖己。\n\n原圖另外的甲是馬祖、丁是小琉球、戊是綠島。不要只看「有水上活動」就選島，應抓每段最有辨識力的族群、景點與地形。',tables=[dict(caption='表（一）離島套裝行程',headers=['行程','規畫內容'],rows=[['行程一','前往古寧頭戰史館等戰地史蹟，重溫昔日戰爭的歷史，晚上還能與三五好友小酌一杯高粱酒。'],['行程二','飽覽壯闊的柱狀玄武岩，盡情享受獨木舟、香蕉船等水上活動的樂趣。'],['行程三','在太平洋上進行達悟族的拼板舟體驗，或探訪島上火山口因雨水蓄積形成的大天池。（※3～6月飛魚季期間不開放拼板舟體驗。）']])],figures=[dict(src=str((D/'evidence/q-16-map.png').relative_to(R)),alt='原卷圖（六）：臺灣本島周邊甲、乙、丙、丁、戊、己六處離島位置，保留原印代號。',caption='原題附圖裁切；僅保留作答所需的離島相對位置與代號。')],student='原卷藍筆D，紅筆訂正C。',tags=['臺灣離島','古寧頭','達悟族'])
add(2,22,20,'Geography','全球產業鏈重整與高附加價值','素有「世界工廠」之稱的中國，在全球產業供應鏈占有舉足輕重的地位。然而，在製造成本提高以及地緣政治影響下，外資及製造業生產基地開始外移。以蘋果手機為例，近年蘋果公司開始把生產基地從中國遷移到印度或亞洲其他國家，僅將部分關鍵零組件留在中國當地製造。此現象反映出在世界產業轉移的過程中，不僅重整了全球產業鏈，也帶動中國的產業升級，中國的地位，從過去是最終消費品的主要出口國，現在逐漸成為關鍵零組件的出口大國。根據上文可以得知，中國在全球產業鏈重整的過程中產生了何種變化？',['中國產業升級為勞力密集型','成為世界最大消費市場之一','轉型生產高附加價值的產品','國際貿易從出超轉變為入超'],'C',['勞力密集型主要依賴大量人力，與本題由成品組裝走向低替代性的關鍵零組件方向相反。','文中談的是生產與出口角色，沒有提供消費市場規模的證據。','由最終消費品轉向低替代性、影響產品性能的關鍵零組件，顯示生產內容向較高附加價值提升。','文中沒有進出口總額，不能判斷出超或入超，更不能推論兩者轉換。'],'選C。題幹明說中國的出口角色從最終消費品，逐漸轉向部分關鍵零組件；註解又指出這類零組件替代性低、對產品性能影響大。依本題語境，代表產業轉型，往較高附加價值的生產環節提升。\n\n不能把「升級」理解為更依賴大量低成本人力；也不能從生產基地遷移，直接推論消費市場大小或貿易順逆差。這是依題文判斷產業角色的改變，不表示所有零組件都必然高價值。',passage='註：關鍵零組件：指替代性低、且對產品性能影響甚鉅的零組件，如觸控感應器、鋰電池等。',student='原卷藍筆A，紅筆訂正C。',tags=['全球產業鏈','關鍵零組件','產業升級'])
add(3,23,23,'History','霧社事件後的集團移住','圖（八）是二十世紀前期，花蓮部分地區原住民部落分布的變遷圖，觀察圖中部落分布的情形，其變遷的原因最可能與下列何者有關？',['清法戰爭後，政府推動開山撫番措施','霧社事件之後，政府執行的原住民政策','二二八事件時，政府在東部展開清鄉工作','社會運動興起，原住民發起還我土地運動'],'B',['清法戰爭屬清治時期，與本題二十世紀前期日治時期的背景不符。','霧社事件後，日本統治當局擴大集團移住政策，強迫山區部落遷往較易統治的地區，符合分布變化。','二二八事件在戰後，年代不符；圖示也不是清鄉的直接證據。','還我土地運動屬較晚近的原住民族社會運動，不是本圖日治時期的政府遷移政策。'],'選B。先以「二十世紀前期」定位日治時期，再比較圖中十年後部落分布的改變。霧社事件後，日本統治當局推行大規模集團移住，將山區分散部落遷往較易控制、管理的地區，最符合題目。\n\n原圖沒有每個部落的名稱，也沒有逐點遷移路線；因此只判斷整體分布改變與政策背景，不自行為各點命名或補出精確路線。A、C、D各自的時代背景與本題不合。\n\n查核：[中央研究院臺灣史研究所〈原住民集團移住相關研究〉](https://www.ith.sinica.edu.tw/quarterly_download.php?filename=148239124712.pdf&name=04%E8%91%89%E9%AB%98%E8%8F%AF3%E6%A0%A1%E7%A8%BF1130.pdf)。',figures=[dict(src=str((D/'evidence/q-23-map.png').relative_to(R)),alt='原卷圖（八）：臺灣位置示意與花蓮部分地區原住民部落分布，箭頭標示10年後，兩幅地圖以黑點表示原住民部落。',caption='原題附圖裁切；保留兩時點分布、10年後箭頭與黑點圖例。')],student='原卷藍筆A，紅筆訂正B。',tags=['霧社事件','集團移住','日治時期'],sources=[dict(title='中央研究院臺灣史研究所研究：霧社事件後集團移住',url='https://www.ith.sinica.edu.tw/quarterly_download.php?filename=148239124712.pdf&name=04%E8%91%89%E9%AB%98%E8%8F%AF3%E6%A0%A1%E7%A8%BF1130.pdf')])
add(4,24,24,'History','土地改革與進口替代時期','一位學者在書中寫道：「政府透過『耕者有其田』政策，使承租土地的佃農，從此有了自己的土地。這個表面看起來是農業政策的改革，實質上卻促成臺灣中小企業的興起。因為隨著自耕農收入的增加和購買力提升，促進工業產品在國內市場的發展；而土地被徵收的地主，也轉往工商業發展，奠定工商業經濟成長的基礎。」上文所描述的臺灣最可能處於哪個經濟發展的階段？',['實行「進口替代」政策','推動「十大建設」計畫','加入「世界貿易組織」','落實「工業日本，農業臺灣」'],'A',['耕者有其田及購買力上升、國內市場工業發展，對應戰後1950年代進口替代階段。','十大建設是1970年代的重大基礎建設，較晚於題文土地改革與早期工業發展。','臺灣2002年加入WTO，遠晚於耕者有其田政策所指背景。','工業日本、農業臺灣是日治時期的殖民經濟分工，與戰後土地改革不符。'],'選A。題文以「耕者有其田」的土地改革作為線索，並描述自耕農收入與購買力提高，帶動國內工業品市場；原地主部分資金轉向工商業，也有助工業發展。這最接近戰後1950年代進口替代階段，以本地工業生產取代部分進口商品。\n\nB十大建設、C加入WTO的年代都更晚；D是日治時期的殖民地經濟分工，不能和戰後土地改革混為一談。',student='原卷藍筆B，紅筆訂正A。',tags=['耕者有其田','進口替代','土地改革'])
print('Prepared',len(manifest['items']),'source64 new question drafts')
